def _deviner_type(motif):
    motif = (motif or "").lower()
    if "transf" in motif or "chang" in motif:
        return "transfert"
    if "abandon" in motif:
        return "abandon"
    if "cycle" in motif or "diplom" in motif or "diplôm" in motif or "termin" in motif:
        return "fin_cycle"
    return "archive"


def classer_sorties_existantes(apps, schema_editor):
    """Élèves déjà inactifs : nature de sortie déduite du motif saisi (« Archivé » par défaut), et
    une première entrée d'historique pour que leur sortie ne soit pas perdue à la restauration."""
    EleveProfile = apps.get_model("people", "EleveProfile")
    HistoriqueStatutEleve = apps.get_model("people", "HistoriqueStatutEleve")
    for eleve in EleveProfile.objects.filter(actif=False).select_related("classe"):
        eleve.type_sortie = _deviner_type(eleve.motif_sortie)
        eleve.save(update_fields=["type_sortie"])
        HistoriqueStatutEleve.objects.create(
            eleve=eleve, evenement="sortie", type_sortie=eleve.type_sortie,
            date=eleve.date_sortie or eleve.date_inscription, motif=eleve.motif_sortie,
            classe=eleve.classe, annee_scolaire_id=eleve.classe.annee_scolaire_id if eleve.classe else None,
        )


